interface QuotesWidgetProps {
  locale: string;
}

export function QuotesWidget({ locale }: QuotesWidgetProps) {
  const idx = dayOfYear() % QUOTES.length;
  const quote = QUOTES[idx];
  const text = locale === 'pt' && quote.textPt ? quote.textPt : quote.text;

  return (
    <Wrapper>
      <Header>{locale === 'pt' ? 'Citacao do dia' : 'Daily quote'}</Header>
      <QuoteBlock>
        <QuoteText>{text}</QuoteText>
        <Author>&mdash; {quote.author}</Author>
      </QuoteBlock>
    </Wrapper>
  );
}
