import { useState, useCallback, useEffect } from 'react';
import { putSetting, getSetting } from '@atlantis/shared';

// ─── Types ──────────────────────────────────────────────────────────────────

export type Locale = 'en' | 'pt';

export type TranslationKeys = Record<string, Record<Locale, string>>;

// ─── Global translations ────────────────────────────────────────────────────
// Shared across all apps. Apps can override any key via createT().

const GLOBAL_KEYS: TranslationKeys = {
  // Time ago
  'time.justNow':     { en: 'just now',      pt: 'agora mesmo' },
  'time.mAgo':        { en: '{n}m ago',       pt: 'há {n}m' },
  'time.hAgo':        { en: '{n}h ago',       pt: 'há {n}h' },
  'time.dAgo':        { en: '{n}d ago',       pt: 'há {n}d' },

  // Common UI
  'updated':          { en: 'updated {age}',  pt: 'atualizado {age}' },
  'refresh':          { en: 'Refresh',        pt: 'Atualizar' },
  'loading':          { en: 'Loading…',       pt: 'A carregar…' },
  'noData':           { en: 'No data available',         pt: 'Sem dados disponíveis' },
  'noDescription':    { en: 'No description provided.',  pt: 'Sem descrição.' },
  'failedToFetch':    { en: 'Failed to fetch',           pt: 'Erro ao carregar' },
  'perWeek':          { en: '/ wk',           pt: '/ sem' },
};

// ─── Locale persistence ─────────────────────────────────────────────────────
// localStorage for synchronous initial render, IndexedDB (via putSetting) as
// the durable source of truth that syncs with Supabase when authenticated.

const LS_KEY = 'atlantis:locale';
const DB_KEY = 'shell:locale';

function isLocale(v: string | null | undefined): v is Locale {
  return v === 'en' || v === 'pt';
}

export function loadLocale(): Locale {
  try {
    const stored = localStorage.getItem(LS_KEY);
    if (isLocale(stored)) return stored;
  } catch { /* blocked storage */ }
  return 'en';
}

export function saveLocale(locale: Locale): void {
  try { localStorage.setItem(LS_KEY, locale); } catch { /* noop */ }
  putSetting(DB_KEY, locale).catch(() => { /* noop — IDB may not be ready */ });
}

/** Hydrate localStorage from IndexedDB on startup (async, fire-and-forget). */
function hydrateFromDb() {
  getSetting(DB_KEY)
    .then((v) => {
      if (isLocale(v)) {
        try { localStorage.setItem(LS_KEY, v); } catch { /* noop */ }
      }
    })
    .catch(() => { /* IDB not available */ });
}
hydrateFromDb();

// ─── useLocale hook ─────────────────────────────────────────────────────────

export function useLocale(): [Locale, (locale: Locale) => void] {
  const [locale, setLocaleState] = useState<Locale>(loadLocale);

  const setLocale = useCallback((next: Locale) => {
    setLocaleState(next);
    saveLocale(next);
    window.dispatchEvent(new CustomEvent('atlantis:locale-change', { detail: next }));
  }, []);

  useEffect(() => {
    const handler = (e: Event) => {
      const next = (e as CustomEvent<Locale>).detail;
      setLocaleState(next);
    };
    window.addEventListener('atlantis:locale-change', handler);
    return () => window.removeEventListener('atlantis:locale-change', handler);
  }, []);

  // Hydrate from IDB on mount (may override localStorage value)
  useEffect(() => {
    getSetting(DB_KEY).then((v) => {
      if (isLocale(v) && v !== locale) {
        try { localStorage.setItem(LS_KEY, v); } catch { /* noop */ }
        setLocaleState(v);
      }
    }).catch(() => { /* noop */ });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return [locale, setLocale];
}

// ─── Translation factory ────────────────────────────────────────────────────
// createT() merges global keys with app-specific keys and returns a t() function.

export type TFunction = (key: string, vars?: Record<string, string | number>) => string;

export function createT(locale: Locale, appKeys?: TranslationKeys): TFunction {
  const merged = appKeys ? { ...GLOBAL_KEYS, ...appKeys } : GLOBAL_KEYS;

  return (key: string, vars?: Record<string, string | number>): string => {
    const template = merged[key]?.[locale] ?? key;
    if (!vars) return template;
    return Object.entries(vars).reduce(
      (s, [k, v]) => s.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v)),
      template,
    );
  };
}

// ─── Localized timeAgo ─────────────────────────────────────────────────────

export function localizedTimeAgo(dateStr: string, t: TFunction): string {
  const ms = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(ms / 60_000);
  if (mins < 1) return t('time.justNow');
  if (mins < 60) return t('time.mAgo', { n: mins });
  const hours = Math.floor(mins / 60);
  if (hours < 24) return t('time.hAgo', { n: hours });
  return t('time.dAgo', { n: Math.floor(hours / 24) });
}

export function localizedAge(date: Date, t: TFunction): string {
  const mins = Math.floor((Date.now() - date.getTime()) / 60_000);
  if (mins < 1) return t('time.justNow');
  if (mins < 60) return t('time.mAgo', { n: mins });
  return t('time.hAgo', { n: Math.floor(mins / 60) });
}
